-- TurisData Canarias · copia en texto de turisdata.db (datos SINTÉTICOS)
-- Por si turisdata.db no se abre bien: en DB Browser, Archivo > Nueva base de datos (guardar como turisdata.db),
-- cancelar el asistente de tabla y luego Archivo > Importar > Base de datos desde archivo SQL... y elegir este archivo.
BEGIN TRANSACTION;
CREATE TABLE "alojamientos" (
"id_alojamiento" INTEGER,
  "nombre" TEXT,
  "isla" TEXT,
  "categoria" TEXT,
  "plazas" INTEGER
);
CREATE TABLE "clientes" (
"id_cliente" INTEGER,
  "pais" TEXT,
  "email_hash" TEXT,
  "cliente_desde" TEXT
);
CREATE TABLE "reservas" (
"id_reserva" INTEGER,
  "id_cliente" INTEGER,
  "id_alojamiento" INTEGER,
  "fecha_reserva" TEXT,
  "fecha_llegada" TEXT,
  "antelacion_dias" INTEGER,
  "noches" INTEGER,
  "adultos" INTEGER,
  "ninos" INTEGER,
  "tipo_habitacion" TEXT,
  "regimen" TEXT,
  "canal" TEXT,
  "pais_origen" TEXT,
  "tarifa" TEXT,
  "deposito" TEXT,
  "precio_noche" REAL,
  "peticiones_especiales" INTEGER,
  "cliente_repetidor" INTEGER,
  "cancelaciones_previas" INTEGER,
  "cancelada" INTEGER
);
COMMIT;
